    }

    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
        Object value = fixture.get(key);
        return value == null ? List.of() : (List<Map<String, Object>>) value;
    }
}
-- A whole client can be tax exempt: none of their invoices carry any sales tax or levy, whatever the
-- lines say. Each invoice carries whether it is tax exempt (taken from its client), so a sent invoice
-- keeps the figures it was issued with. Existing clients and invoices are taxed as before, so no
-- amounts change.
ALTER TABLE client ADD COLUMN tax_exempt BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE invoice ADD COLUMN tax_exempt BOOLEAN DEFAULT FALSE NOT NULL;
-- An invoice can also take a flat amount off what its line items add up to, on top of (or instead of)
-- the percentage discount. It never takes off more than is left after the percentage. Existing
-- invoices have no flat discount, so their amounts are unchanged.
ALTER TABLE invoice ADD COLUMN discount_amount DECIMAL(12, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_discount_amount_non_negative CHECK (discount_amount >= 0);
-- A client can be flagged a key account, so the office can pick out its most important clients at a
-- glance. Existing clients are not key accounts.
ALTER TABLE client ADD COLUMN key_account BOOLEAN DEFAULT FALSE NOT NULL;
-- A single line item can take its own percentage off what it charges. The line's amount is then what it
-- charges less its discount, and the invoice is worked out from those discounted lines. Existing lines
